82	// polished gold, art-directed in DISPLAY colours measured on the approved picture (then pjInverse like the plate):
83	// groove (110,35,5) / shadow band (168,70,18) / mid (205,97,28) / lit (245,143,38) / hot lip (255,204,77) / glint.
84	// Each ring = a broad polished band that brightens toward its lip, a bright rounded lip with hot spots, a thin dark groove;
85	// the far rings warm toward the glowing vanishing point; violet / pink water reflections on the lower walls.
86	const GOLD_FRAG = /* glsl */ `
87	uniform sampler2D uPlate;
88	uniform vec4 uPjPost;
89	uniform vec2 uPjRes;
90	uniform float uAway;
91	uniform vec3 uAxO;
92	uniform vec3 uAxD;
93	uniform vec3 uAxU;
94	uniform vec3 uAxR;
95	uniform float uNB;
96	uniform float uP;
97	uniform float uLipBulb;
98	uniform float uBulbR;
99	uniform float uLen;
100	uniform vec4 uTone;        // band base, lip base, opening base, streak strength
101	uniform sampler2D uRingTile; // tile_ring.png: the painted ring colour at every angle (rows 56..176 = band near edge .. lip)
102	uniform float uPaint;      // how much of the painted ring colour drives the bands (m04paint)
103	uniform float uBulge;      // r13 m04bulge: each band shaded as a ROUNDED tube (bright middle, darker edges) like the painted rings
104	uniform float uCopper;     // r13 m04copper: rich polished COPPER-gold ramp (dark maroon grooves -> copper -> warm-gold highlights)
105	uniform float uGoldY;      // m04gold: polished YELLOW-gold ramp (bright yellow-white highlights), fewer magenta tints
106	uniform float uMouthT;     // m04mouth: the painted mouth ring texture on the opening (tile_mouth.png)
107	uniform sampler2D uMouthTex;
108	uniform vec3 uMouthRho;    // tile rows: rho at the top row, rho at the bottom row (fitted mouth plane z0); z: rho offset
109	                           // (the painted band lies 0.1 u inside the fitted outer radius: lips onto the modeled lips)
110	uniform vec3 uProjPos;
111	uniform float uRPaint;     // r15 m04rpaint: mix of the user's PAINTED inner ring (tile_ring_paint.png) on every inner ring band
112	uniform sampler2D uRTex;   // cols psi -pi..pi (0 = top, + = right), rows s 0 (painted groove) .. 1 (next groove), deeper
113	uniform vec4 uRLip;        // x: painted lip-line s, y: modeled u that carries the painted lip line, z: modeled shading amount,
114	                           // w: modeled u where the painted groove begins (held dark to the period end)
115	uniform float uRJit;       // per-ring angle offset (rad, +-): the painted highlights do not line up ring after ring
116	uniform vec2 uRWarm;       // r16 m04rwarm: x = amount, y = where the grade starts (fraction of the camera -> end-glow distance)
117	uniform vec4 uRDots;       // r16 m04rpdots: x = amount, y = dot cells per ring, z = fraction of cells lit, w = core radius (u)
118	uniform float uRVar;       // r17 m04rpvar: number of painted rings stacked in the atlas (0 = the single painted ring 1)
119	uniform vec4 uRPol;        // r18 m04rpol: x amount, y luma pivot, z contrast gain above it, w below it
120	uniform vec2 uRPol2;       // r18 m04rpol: x sharp sheen (reflection of the bright end), y grazing-angle brightening
121	uniform vec4 uRCr;         // r18 m04rpcr: x amount, y bright lip line half width, z dark lip-edge line half width, w band-start corner (u)
122	uniform vec4 uRNear;       // r19b m04rnear: x amount, y target sub-band length (world u), z/w sub-band size on screen (px of a
123	                           // 1536 px tall portrait view, from world length, distance and foreshortening) where the detail starts / is full
124	uniform vec4 uRNear2;      // r19b m04rnear: x painted band grade per sub-band, y rim + groove lines, z yellow-gold grade, w pink / violet reflection
125	uniform vec4 uRNear3;      // r19b m04rnear: x bulbs on the sub-rims, y highlight lift, z corridor ring growth (m04rfg), w lip + groove size (u)
126	uniform vec4 uRNear4;      // r19b m04rnear: x bulbs per sub-rim, y fraction lit, z highlight core sharpness, w bulb size
127	uniform vec4 uRMat;        // r20 m04rmat: x amount, y mid-tone darkening, z mid-tone de-yellowing, w spare
128	uniform vec4 uRNear6;      // r20 m04rnear: x painted light riding on the band grade, y grade exponent along the sub-band, z fine machined lines, w their spacing (ring units)
129	uniform vec4 uRNear5;      // r20 m04rnear: x highlight floor round the ring (0 = hot spots only), y static yellow glows, z rim line
130	                           // offset before the sub-rim (ring units), w the painted band re-drawn on every sub-band (m04rntex)
131	#ifdef RFEW
132	uniform float uRFewG;      // r18 m04rfew: height of the telescope's shrink centre (group units, from the axis; < 0 = below)
133	uniform vec2 uRFewW;       // r18 m04rfew: x = ring scale where the deep rings reach warm yellow-white, y = amount (m04rfw, m04rfk)
134	uniform vec3 uRFewE;       // r18 m04rfew: world position of the telescope's end (the light)
135	uniform vec3 uRFewL;       // r18 m04rfew: light strength, core and glow angular radius (rad) (m04rfl, m04rfc, m04rfo)
136	varying vec2 vF;
137	#endif
138	varying vec4 vProj;
139	varying vec3 vW;
140	varying vec3 vN;
141	varying vec2 vK;            // x: part (0 band, 1 lip, 2 groove, 3 opening face, 4 end glow), y: ring index (-1 = opening)
142	${PROJ05_INVERSE}
143	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
144	vec3 goldRamp(float x) {
145	  x = clamp(x, 0.0, 1.0) * 5.0;
146	  vec3 c0 = vec3(0.43, 0.14, 0.02), c1 = vec3(0.66, 0.27, 0.07), c2 = vec3(0.80, 0.38, 0.11);
147	  vec3 c3 = vec3(0.96, 0.56, 0.15), c4 = vec3(1.0, 0.80, 0.30), c5 = vec3(1.0, 0.96, 0.80);
148	  if (x < 1.0) return mix(c0, c1, x);
149	  if (x < 2.0) return mix(c1, c2, x - 1.0);
150	  if (x < 3.0) return mix(c2, c3, x - 2.0);
151	  if (x < 4.0) return mix(c3, c4, x - 3.0);
152	  return mix(c4, c5, x - 4.0);
153	}
154	vec3 goldRampC(float x) {
155	  x = clamp(x, 0.0, 1.0) * 5.0;
156	  vec3 c0 = vec3(0.17, 0.04, 0.03), c1 = vec3(0.42, 0.13, 0.06), c2 = vec3(0.66, 0.29, 0.12);
157	  vec3 c3 = vec3(0.86, 0.50, 0.22), c4 = vec3(0.98, 0.76, 0.44), c5 = vec3(1.0, 0.95, 0.86);
158	  if (x < 1.0) return mix(c0, c1, x);
159	  if (x < 2.0) return mix(c1, c2, x - 1.0);
160	  if (x < 3.0) return mix(c2, c3, x - 2.0);
161	  if (x < 4.0) return mix(c3, c4, x - 3.0);
162	  return mix(c4, c5, x - 4.0);
163	}
164	vec3 goldRampY(float x) {
165	  x = clamp(x, 0.0, 1.0) * 5.0;
166	  vec3 c0 = vec3(0.52, 0.22, 0.03), c1 = vec3(0.76, 0.40, 0.07), c2 = vec3(0.89, 0.55, 0.12);
167	  vec3 c3 = vec3(0.98, 0.72, 0.20), c4 = vec3(1.0, 0.87, 0.42), c5 = vec3(1.0, 0.98, 0.86);
168	  if (x < 1.0) return mix(c0, c1, x);
169	  if (x < 2.0) return mix(c1, c2, x - 1.0);
170	  if (x < 3.0) return mix(c2, c3, x - 2.0);
171	  if (x < 4.0) return mix(c3, c4, x - 3.0);
172	  return mix(c4, c5, x - 4.0);
173	}
174	// a few long highlight streaks around the ring (painted smears), different on every ring
175	float streaks(float ang, float ring) {
176	  float s = 0.0;
177	  for (int i = 0; i < 4; i++) {
178	    float fi = float(i);
179	    float c = (h21(vec2(ring, fi * 3.1)) * 2.0 - 1.0) * 2.6;
180	    float w = 0.12 + 0.30 * h21(vec2(ring, fi * 5.7));
181	    float d = ang - c; d = mod(d + 3.14159, 6.28318) - 3.14159;
182	    s += (0.45 + 0.55 * h21(vec2(ring, fi * 9.3))) * exp(-d * d / (w * w));
183	  }
184	  return s;
185	}
