213	    // the far glow (painted vanishing point): small warm-white core, orange-gold outside with faint far rings
214	    // soft warm-white core, yellow-orange glow, orange toward the rim (matches the far bands), no hard target rings
215	    float rad = clamp(rr / 3.6, 0.0, 1.0);

